package net.battlespades.bot;
import java.util.*;
import net.battlespades.entities.ProjectileSpec;
import net.battlespades.physics.PlayerPhysics.Vector;
import static net.battlespades.bot.BotMessages.*;
import static net.battlespades.bot.BotVectors.*;

/** Stocked projectile choices remain proposals; the gameplay gateway must recheck live launch lanes. */
final class BrainOriented {
    private static final org.tomlj.TomlParseResult DATA=net.battlespades.catalog.SourceCatalog.load("bot-live");
    private static final Set<Integer> TOOLS=Set.copyOf(net.battlespades.catalog.SourceCatalog.integers(DATA.getArray("oriented_tools"))),ROCKETS=Set.copyOf(net.battlespades.catalog.SourceCatalog.integers(DATA.getArray("rocket_tools")));
    private static final int DRILL=Math.toIntExact(DATA.getLong("drill_tool"));
    record Choice(int tool,double aimOffset){}
    private final Thread owner=Thread.currentThread();private final Map<Integer,Double> teamReady=new HashMap<>();
    void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Brain projectiles outside owner");}
    void reset(){owned();teamReady.clear();}
    Choice choose(BotNavigationWorld world,Perception frame,Player p,Player target,BotBrainState state,BotProfile profile,double now){owned();if(p.reloading()||now<state.nextOrientedAt||now<teamReady.getOrDefault(p.team(),Double.NEGATIVE_INFINITY)||now-state.acquiredAt<profile.reactionTime())return null;var stock=new HashMap<Integer,Integer>();for(var s:p.orientedStock())stock.put(s.tool(),s.count());double gap=distance(p.eye(),target.eye());int cluster=(int)frame.players().stream().filter(q->q.team()!=p.team()&&q.alive()&&q.spawned()&&distance(q.position(),target.position())<=8).count();Choice best=null;double bestScore=Double.NEGATIVE_INFINITY;for(int tool:p.loadout()){if(!TOOLS.contains(tool)||stock.getOrDefault(tool,0)<=0)continue;var spec=ProjectileSpec.TOOLS.get(tool);if(spec==null)continue;double radius=Math.max(0,spec.radius()),minimum=Math.max(radius+4,10),maximum=switch(spec.motion()){case BOUNCE->42;case STICK->48;case DEPLOY->52;case CONTACT->92;};if(tool==DRILL){minimum=9;maximum=42;}else if(ROCKETS.contains(tool)){minimum=Math.max(radius+5,12);maximum=100;if(!world.lineOfSight(p.eye(),target.eye()))continue;}if(gap<minimum||gap>maximum||!safe(frame,p,target.position(),tool,false)||!laneClear(frame,p,target.eye())||cluster<=1&&target.health()<=22)continue;double score=Math.min(250,Math.max(0,spec.damage()))/250+radius/10+Math.max(0,cluster-1)*.8+(ROCKETS.contains(tool)?.35:0);if(score>bestScore||score==bestScore&&(best==null||tool<best.tool())){bestScore=score;best=new Choice(tool,aimOffset(tool,gap));}}if(best!=null){state.nextOrientedAt=now+5.5+(1-profile.creativity())*4+Math.floorMod(p.id(),3)*.6;teamReady.put(p.team(),now+1);}return best;}
    static double aimOffset(int tool,double distance){var spec=ProjectileSpec.TOOLS.get(tool);var speeds=DATA.getTable("oriented_speeds");Object raw=speeds.get(Integer.toString(tool));double speed=raw instanceof Number n?n.doubleValue():0;if(spec==null||speed<=1e-6)return 0;double time=Math.max(0,distance)/speed,drop=.5*DATA.getDouble("projectile_gravity")*Math.max(0,spec.gravity())*time*time;return -Math.min(spec.motion()==ProjectileSpec.Motion.BOUNCE||spec.motion()==ProjectileSpec.Motion.STICK?9:6,drop);}
    static boolean laneClear(Perception frame,Player p,Vector target){var start=p.eye();double dx=target.x()-start.x(),dy=target.y()-start.y(),dz=target.z()-start.z(),length=dx*dx+dy*dy+dz*dz;if(length<=1e-6)return false;for(var q:frame.players()){if(q.id()==p.id()||q.team()!=p.team()||!q.alive()||!q.spawned())continue;double fraction=((q.eye().x()-start.x())*dx+(q.eye().y()-start.y())*dy+(q.eye().z()-start.z())*dz)/length;if(fraction<=.03||fraction>=.97)continue;var closest=new Vector(start.x()+dx*fraction,start.y()+dy*fraction,start.z()+dz*fraction);if(distance(q.eye(),closest)<=2.25)return false;}return true;}
    static boolean safe(Perception frame,Player p,Vector position,int tool,boolean ignoreObserver){var spec=ProjectileSpec.TOOLS.get(tool);if(spec==null)return false;double radius=Math.max(0,spec.radius());if(radius<=0||!ignoreObserver&&distance(p.position(),position)<=radius+3)return false;for(var q:frame.players())if(q.id()!=p.id()&&q.team()==p.team()&&q.alive()&&q.spawned()&&distance(q.position(),position)<=radius+1.5)return false;for(var e:frame.entities())if(e.alive()&&e.hazardous()&&distance(e.position(),position)<=radius+Math.max(0,e.blastRadius())+1)return false;return true;}
    static void progress(BotBrainState state,Vector position,double now){if(!state.combatWantsMovement){state.combatProgressPosition=position;state.combatProgressAt=state.combatLastAt=now;state.combatStallStage=0;return;}if(state.combatProgressPosition==null||now-state.combatLastAt>.75){state.combatProgressPosition=position;state.combatProgressAt=now;state.combatStallStage=0;}else if(flat(position,state.combatProgressPosition)>=.4){state.combatProgressPosition=position;state.combatProgressAt=now;state.combatStallStage=0;}else if(now-state.combatProgressAt>=1){state.combatProgressPosition=position;state.combatProgressAt=now;state.combatStallStage=Math.min(4,state.combatStallStage+1);}state.combatLastAt=now;}
}
